class MinStack {
    private Deque<Integer> values;
    private Deque<Integer> mins;

    public MinStack() {
        values = new ArrayDeque<>();
        mins = new ArrayDeque<>();
    }

    public void push(int val) {
        values.push(val);
        if (mins.isEmpty() || val <= mins.peek()) {
            mins.push(val);
        }
    }

    public void pop() {
        int removed = values.pop();
        if (removed == mins.peek()) {
            mins.pop();
        }
    }

    public int top() {
        return values.peek();
    }

    public int getMin() {
        return mins.peek();
    }
}

import java.util.*;

class MinStack {
    private Deque<Integer> values;
    private Deque<int[]> mins;

    public MinStack() {
        values = new ArrayDeque<>();
        mins = new ArrayDeque<>();
    }

    public void push(int val) {
        values.push(val);
        if (mins.isEmpty() || val < mins.peek()[0]) {
            mins.push(new int[]{val, 1});
        } else if (val == mins.peek()[0]) {
            mins.peek()[1]++;
        }
    }

    public void pop() {
        int removed = values.pop();
        if (removed == mins.peek()[0]) {
            mins.peek()[1]--;
            if (mins.peek()[1] == 0) {
                mins.pop();
            }
        }
    }

    public int top() {
        return values.peek();
    }

    public int getMin() {
        return mins.peek()[0];
    }
}

import java.util.*;

class MinStack {
    private Deque<int[]> stack;

    public MinStack() {
        stack = new ArrayDeque<>();
    }

    public void push(int val) {
        int currentMin = stack.isEmpty() ? val : Math.min(val, stack.peek()[1]);
        stack.push(new int[]{val, currentMin});
    }

    public void pop() {
        stack.pop();
    }

    public int top() {
        return stack.peek()[0];
    }

    public int getMin() {
        return stack.peek()[1];
    }
}

import java.util.*;

class MinStack {
    private Deque<Long> stack;
    private long min;

    public MinStack() {
        stack = new ArrayDeque<>();
    }

    public void push(int val) {
        if (stack.isEmpty()) {
            stack.push(0L);
            min = val;
            return;
        }

        long diff = (long) val - min;
        stack.push(diff);
        if (diff < 0) {
            min = val;
        }
    }

    public void pop() {
        long diff = stack.pop();
        if (diff < 0) {
            min = min - diff;
        }
    }

    public int top() {
        long diff = stack.peek();
        if (diff > 0) {
            return (int) (min + diff);
        }
        return (int) min;
    }

    public int getMin() {
        return (int) min;
    }
}

import java.util.*;

class MinStack {
    private Deque<Long> stack;
    private long min;

    public MinStack() {
        stack = new ArrayDeque<>();
    }

    public void push(int val) {
        if (stack.isEmpty()) {
            min = val;
            stack.push((long) val);
            return;
        }

        if (val <= min) {
            stack.push(min);
            min = val;
        }
        stack.push((long) val);
    }

    public void pop() {
        long removed = stack.pop();
        if (removed == min && !stack.isEmpty()) {
            min = stack.pop();
        }
    }

    public int top() {
        return stack.peek().intValue();
    }

    public int getMin() {
        return (int) min;
    }
}
